package errhance

import (
	"errors"
	"os"
	"path/filepath"
	"testing"
)

func TestOnSaveNoopNeedsNoGoDriver(t *testing.T) {
	for _, src := range []string{
		"package p\n",
		`package p; import "fmt"; func f() error { return fmt.Errorf("context") }`,
		`package p; import "unavailable.example/dependency"; func f() error { return dependency.Call() }`,
		"// Code generated by test. DO NOT EDIT.\n" + validSource,
	} {
		t.Run(src, func(t *testing.T) {
			root := projectFixture(t, map[string]string{"p.go": src})
			path := filepath.Join(root, "p.go")
			before, err := os.Stat(path)
			if err != nil {
				t.Fatal(err)
			}
			t.Setenv("PATH", "")
			report, err := LocalFile(NewSourceConfig(), path)
			if !errors.Is(err, ErrNoChanges) || report.After != src || report.TotalErrorsEnhanced != 0 {
				t.Fatalf("no-op invoked type loader: %+v, %v", report, err)
			}
			after, err := os.Stat(path)
			if err != nil || !os.SameFile(before, after) || !before.ModTime().Equal(after.ModTime()) || readProjectFile(t, path) != src {
				t.Fatalf("no-op changed file: %v", err)
			}
		})
	}
}

func TestOnSaveCandidateStillRequiresTypes(t *testing.T) {
	root := projectFixture(t, map[string]string{"p.go": validSource})
	path := filepath.Join(root, "p.go")
	t.Setenv("PATH", "")
	if report, err := LocalFile(NewSourceConfig(), path); err == nil || errors.Is(err, ErrNoChanges) || report.After != validSource {
		t.Fatalf("candidate bypassed type checking: %+v, %v", report, err)
	}
	if readProjectFile(t, path) != validSource {
		t.Fatal("unvalidated source written")
	}
}

func BenchmarkOnSaveNoop(b *testing.B) {
	root, err := filepath.EvalSymlinks(b.TempDir())
	if err != nil {
		b.Fatal(err)
	}
	path := filepath.Join(root, "p.go")
	const src = `package p; import "fmt"; func F() error { return fmt.Errorf("already wrapped") }`
	if err := os.WriteFile(path, []byte(src), 0600); err != nil {
		b.Fatal(err)
	}
	b.Setenv("PATH", "")
	cfg := NewSourceConfig()
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		if _, err := LocalFile(cfg, path); !errors.Is(err, ErrNoChanges) {
			b.Fatal(err)
		}
	}
}
